describe('Polling functionality', () => {
    beforeEach(() => {
        cy.visit('/your-page-url'); // Replace with the actual URL of the page
    });

    it('should stop polling when navigating away from the page', () => {
        // Start the polling
        cy.intercept('GET', '/api/polling-endpoint').as('pollingRequest');
        cy.wait('@pollingRequest').its('response.statusCode').should('eq', 200);

        // Navigate away from the page
        cy.get('a#navigate-away').click(); // Replace with the actual selector for navigation

        // Verify that polling has stopped
        cy.wait(1000); // Wait for a moment to ensure polling would have occurred
        cy.get('@pollingRequest').should('not.exist');
    });

    it('should continue polling when staying on the page', () => {
        // Start the polling
        cy.intercept('GET', '/api/polling-endpoint').as('pollingRequest');
        cy.wait('@pollingRequest').its('response.statusCode').should('eq', 200);

        // Verify that polling continues
        cy.wait(5000); // Wait for a duration to allow multiple polling requests
        cy.get('@pollingRequest').should('have.length.greaterThan', 1);
    });
});
